SELECT COUNT(*) AS n, SUM(f.ASSET) AS total_asset_k, COUNT(DISTINCT f.CERT) AS banks
FROM raw_financials f
JOIN raw_institutions i ON f.CERT = i.CERT
WHERE i.STNAME = 'Texas' AND f.REPDTE = 20260630;
SELECT CERT, COUNT(*) c FROM raw_institutions GROUP BY CERT HAVING c>1 LIMIT 5;
SELECT COUNT(*) FROM raw_financials WHERE REPDTE=20260630 AND ASSET IS NULL;
